head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkcombobox > E > onclose]<br/>컴포넌트에서 아이템 리스트창이 닫힐때 발생합니다.",
    "validation" : [        
        "사용자에 의해 아이템 선택 상태가 변경된 경우 checkboxClickSync=true 이면 onchange -> onviewchange -> oncheckboxclick 순서로 이벤트가 발생한 후 아이템 리스트창이 닫힐때 onclose 이벤트가 발생합니다.",
        "사용자에 의해 아이템 선택 상태가 변경된 경우 checkboxClickSync=false 이면 oncheckboxclick 이벤트가 발생한 후 아이템 리스트창이 닫힐때 onchange -> onviewchange -> onclose 순서로 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        checkboxClickSync : con_checkboxClickSync.getText(),
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onchange", "onviewchange", "oncheckboxclick", "onclose"]);

    // comp 생성
    $c.gcm.createBasicCheckComboBox(cList, eList);
}



scwin.target1_onclose = function (closeOut) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onclose=====");    
}


scwin.target1_onchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onchange=====");
}


scwin.target1_onviewchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onviewchange=====");
}

scwin.target1_oncheckboxclick = function (index, checked, value) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_oncheckboxclick=====");
}
